import zlib from "node:zlib";

const encoded = "";
const refs = JSON.parse(
  zlib.gunzipSync(Buffer.from(encoded, "base64")).toString("utf8"),
);

export function isKnownHiddenContentRef(ref: string): boolean {
  return Object.values(refs as Record<string, string[]>).some((items) =>
    items.includes(ref),
  );
}
